const $=id=>document.getElementById(id),S=Shootout,F=LAB_DATA,colors=['#166477','#cf643d','#488579','#867451','#9b7796'];let comparison=[],searchRows=[],current={};
const pct=x=>(100*x).toFixed(2)+'%',num=x=>x.toFixed(3),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function table(id,headers,rows){$(id).innerHTML='<div class="tablewrap"><table><thead><tr>'+headers.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function download(name,content,type='text/plain'){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){if(!rows.length)return '';let keys=Object.keys(rows[0]),quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';return keys.map(quote).join(',')+'\n'+rows.map(x=>keys.map(k=>quote(x[k])).join(',')).join('\n');}
function read(){let model={p:+$('p').value,q:+$('q').value,delta:+$('delta').value,pressure:+$('pressure').value,fatigue:+$('fatigue').value,lineupA:[],lineupB:[]};if($('lineup').value!=='none'){model.lineupA=[.3,.2,.1,0,-.1,-.2,-.3,-.2,-.1,0,.1];model.lineupB=$('lineup').value==='shared'?model.lineupA:[.2,.3,0,-.1,.1,-.3,-.2,0,-.1,.2,-.1];}let rules=S.rules.map(x=>({...x}));rules[1].m=rules[2].m=+$('m').value;rules[1].n=rules[2].n=+$('n').value;rules[1].name=`Target (${rules[1].m},${rules[1].n})`;rules[2].name=`Sequential (${rules[2].m},${rules[2].n})`;return {model,rules};}
function chart(id,series,{xmin=0,xmax=1,ymin=0,ymax=1,xlabel='q',ylabel='P(A)'}={}){let el=$(id),vb=el.viewBox.baseVal,W=vb.width,H=vb.height,L=52,R=12,T=22,B=42,x=x=>L+(x-xmin)/(xmax-xmin)*(W-L-R),y=y=>H-B-(y-ymin)/(ymax-ymin)*(H-B-T),parts=[];for(let i=0;i<5;i++){let yy=ymin+i*(ymax-ymin)/4,xx=xmin+i*(xmax-xmin)/4;parts.push(`<line x1="${L}" y1="${y(yy)}" x2="${W-R}" y2="${y(yy)}" stroke="#dce3df"/><text x="${L-8}" y="${y(yy)+4}" text-anchor="end" font-size="10" fill="#687d80">${yy.toFixed(2)}</text><text x="${x(xx)}" y="${H-B+19}" text-anchor="middle" font-size="10" fill="#687d80">${xx.toFixed(xmax>1?0:2)}</text>`);}if(ymin<=.5&&ymax>=.5)parts.push(`<line x1="${L}" y1="${y(.5)}" x2="${W-R}" y2="${y(.5)}" stroke="#6a7c7c" stroke-dasharray="4 4"/>`);series.forEach((s,i)=>parts.push(`<path d="${s.map(([a,b],j)=>(j?'L':'M')+x(a).toFixed(2)+' '+y(b).toFixed(2)).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2.3"/>`));parts.push(`<text x="${W/2}" y="${H-3}" text-anchor="middle" fill="#687d80" font-size="11">${esc(xlabel)}</text><text x="${L}" y="12" fill="#687d80" font-size="10">${esc(ylabel)}</text>`);el.innerHTML=parts.join('');}
function heatmap(rule){let canvas=$('heatmap'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,L=52,T=10,plotW=W-L-16,plotH=H-T-35,N=32;ctx.clearRect(0,0,W,H);for(let i=0;i<N;i++)for(let j=0;j<N;j++){let p=.5+(.4*(i+.5)/N),q=.5+(.4*(j+.5)/N),a=S.exact(rule,{p,q}).win,b=S.exact(S.rules[0],{p,q}).win,d=Math.abs(a-.5)-Math.abs(b-.5),alpha=Math.min(1,Math.abs(d)/.27);ctx.fillStyle=d<0?`rgba(22,100,119,${.12+.85*alpha})`:`rgba(207,100,61,${.12+.85*alpha})`;ctx.fillRect(L+i*plotW/N,T+(N-j-1)*plotH/N,plotW/N+1,plotH/N+1);}ctx.fillStyle='#5e7378';ctx.font='11px system-ui';ctx.fillText('q',12,18);ctx.fillText('p',W/2,H-2);for(let i=0;i<5;i++){let v=(.5+i*.1).toFixed(2);ctx.fillText(v,L+i*plotW/4-10,H-18);ctx.fillText(v,15,T+(1-i/4)*plotH+4);}}
function update(){let {model,rules}=read();if(rules[1].m<1||rules[1].m>12||rules[1].n<1||rules[1].n>12||!Number.isInteger(rules[1].m)||!Number.isInteger(rules[1].n))return;current={model,rules};for(let id of ['p','q','delta','pressure','fatigue'])$(id+'Out').textContent=id==='p'||id==='q'?pct(+$ (id).value):num(+$ (id).value);let iid=!model.delta&&!model.pressure&&!model.fatigue&&!model.lineupA.length;comparison=rules.map((rule,i)=>{let z=S.forward(rule,model,100);if(iid){let e=S.exact(rule,model);z={...z,...e};}return {rule,...z};});$('solverLabel').textContent=iid?'EXACT IID':'100-ROUND PROPAGATION';$('solverNote').textContent=iid?'Win probabilities and expected durations use exact finite-state equations. Tail probabilities use forward propagation.':`Displayed durations are E[min(R,100)] and expected kicks through 100 rounds. Win uncertainty from truncation is at most ${Math.max(...comparison.map(x=>x.residual)).toExponential(2)}. Inputs are hypothetical; this solver does not model latent team shocks.`;
 $('comparison').innerHTML=comparison.map((z,i)=>`<div class="comparison-row"><div class="rulename">${esc(z.rule.name)}<p class="small">${num(z.rounds)} rounds · ${z.kicks.toFixed(2)} kicks<br>SD ${pct(z.sd)} · R>10 ${pct(z.tail)}</p></div><div class="bar"><div class="fill" style="width:${z.win*100}%;background:${colors[i]}"></div></div><div class="rowvalue"><strong>${pct(z.win)}</strong><small>A wins · bias ${(100*(z.win-.5)).toFixed(2)} pp</small></div></div>`).join('');
 let curves=[[],[],[]];for(let i=1;i<=25;i++){let q=.2+i*.03;for(let j=0;j<3;j++){let mo={...model,q},z=iid?S.exact(rules[j],mo):S.forward(rules[j],mo,70);curves[j].push([q,z.win]);}}chart('curve',curves,{xmin:.2,xmax:.95});chart('duration',comparison.slice(0,3).map(z=>{let t=0;return z.pmf.slice(0,15).map((v,i)=>[i+1,t+=v]);}),{xmin:1,xmax:15,xlabel:'Rounds started',ylabel:'P(R ≤ round)'});heatmap(rules[1]);$('mcStatus').textContent='';}
let timer;for(let id of ['p','q','delta','pressure','fatigue','lineup','m','n'])$(id).addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(update,100);});function preset(p,q,d=0,pressure=0){$('p').value=p;$('q').value=q;$('delta').value=d;$('pressure').value=pressure;$('fatigue').value=0;$('lineup').value='none';update();}$('paperPreset').onclick=()=>preset(.75,.6);$('nullPreset').onclick=()=>preset(.75,.75);$('behaviorPreset').onclick=()=>preset(.75,.75,.2,.1);
$('mcButton').onclick=async()=>{let N=+$('trials').value,seed=+$('seed').value;if(!Number.isInteger(N)||N<1000||N>100000||!Number.isInteger(seed)||seed<0||seed>4294967295){$('mcStatus').textContent='Use 1,000–100,000 trials and an integer seed between 0 and 4294967295.';return;}$('mcButton').disabled=true;$('mcStatus').textContent='Running reproducible simulations…';await new Promise(r=>setTimeout(r,30));try{let {model,rules}=read(),rows=rules.map((r,i)=>({name:r.name,...S.mc(r,model,N,seed+i,100)}));table('mcStatus',['Rule','MC A wins','95% Wilson interval','Censored','Seed'],rows.map(x=>[x.name,pct(x.win),x.ci.map(pct).join(' – '),x.censored,x.seed]));}finally{$('mcButton').disabled=false;}};
$('export').onclick=()=>download('shootout-comparison.csv',csv(comparison.map(x=>({rule:x.rule.name,...current.model,win_a:x.win,win_upper:x.win+x.residual,rounds:x.rounds,kicks:x.kicks,sd:x.sd,tail10:x.tail,seed:+$('seed').value,horizon:100}))), 'text/csv');$('exportConfig').onclick=()=>download('shootout-scenario.json',JSON.stringify({...current,seed:+$('seed').value,N:+$('trials').value,horizon:100},null,2),'application/json');
function optimize(){let pmin=+$('pmin').value,pmax=+$('pmax').value,qmin=+$('qmin').value,qmax=+$('qmax').value,max=+$('maxTarget').value,min=+$('minTarget').value,limit=+$('roundLimit').value;if(!(0<pmin&&pmin<=pmax&&pmax<1&&0<qmin&&qmin<=qmax&&qmax<1&&Number.isInteger(max)&&max>=2&&max<=12&&Number.isInteger(min)&&min>=1&&min<=max&&limit>0)){ $('robustStatus').textContent='Check probability bounds, integer targets, and positive duration limit.';return;}let scenarios=[];for(let i=0;i<3;i++)for(let j=0;j<3;j++)scenarios.push({p:pmin+(pmax-pmin)*i/2,q:qmin+(qmax-qmin)*j/2});let candidates=[S.rules[0]];for(let m=min;m<=max;m++)for(let n=min;n<=m;n++)candidates.push({kind:'target',m,n,order:'ABAB',name:`Target (${m},${n})`});searchRows=candidates.map(rule=>{let z=scenarios.map(m=>S.exact(rule,m)),worst=Math.max(...z.map(x=>Math.abs(x.win-.5))),duration=Math.max(...z.map(x=>x.rounds));return {rule:rule.name,m:rule.m,n:rule.n,worst_bias:worst,worst_rounds:duration,feasible:duration<=limit,pmin,pmax,qmin,qmax,grid_points:9};}).sort((a,b)=>Number(b.feasible)-Number(a.feasible)||a.worst_bias-b.worst_bias||a.worst_rounds-b.worst_rounds);let winner=searchRows.find(x=>x.feasible);$('robustStatus').textContent=winner?`${winner.rule}: worst bias ${pct(winner.worst_bias)}, worst duration ${num(winner.worst_rounds)} rounds. Finite-grid optimum among ${candidates.length} candidates.`:'No feasible candidate. Relax the duration limit or targets.';table('robustTable',['Rule','Worst |bias|','Worst rounds','Feasible'],searchRows.slice(0,12).map(x=>[x.rule,pct(x.worst_bias),num(x.worst_rounds),x.feasible?'yes':'no']));}
$('optimize').onclick=optimize;$('exportRobust').onclick=()=>download('robust-grid.csv',csv(searchRows),'text/csv');
for(let b of document.querySelectorAll('nav button'))b.onclick=()=>{for(let x of document.querySelectorAll('nav button'))x.classList.toggle('active',x===b);for(let v of document.querySelectorAll('.view'))v.classList.toggle('active',v.id===b.dataset.tab);};
table('paperTable',['Targets','Paper q*','Computed q*','Paper ER (.75,.60)','Computed ER'],F.summary.reproduction.map(x=>[`(${x.m},${x.n})`,x.paper_q.toFixed(2),x.q_balancing.toFixed(6),x.paper_rounds.toFixed(2),x.rounds.toFixed(6)]));table('mcRobust',['Rule','Worst bias','95% upper bound','Capped ER upper'],F.mcRobust.map(x=>[x.kind==='standard'?x.order:`(${x.m},${x.n})`,pct(+x.worst_bias),pct(+x.bias_upper),num(+x.duration_upper)]));$('holdout').textContent='Independent holdout at δ=.2: selected Catch-Up A wins '+pct(F.summary.mc_holdout.win_a)+', Wilson interval '+F.summary.mc_holdout.ci95.map(pct).join(' – ')+'.';
const positions=F.empirical.estimates.filter(x=>x.kind==='position'&&+x.label<=10);table('empTable',['Kick','Observed attempts','Conversion','Bootstrap 95%'],positions.map(x=>[Number(x.label)%2?'A'+Math.ceil(+x.label/2):'B'+Math.ceil(+x.label/2),x.attempts,pct(x.conversion),x.shootout_bootstrap_95.map(pct).join(' – ')]));
function empiricalChart(){let el=$('empChart'),W=900,H=320,L=52,B=40,T=20,y=v=>H-B-(v-.6)/.3*(H-T-B),parts=[];for(let i=0;i<=3;i++){let v=.6+i*.1;parts.push(`<line x1="${L}" y1="${y(v)}" x2="885" y2="${y(v)}" stroke="#dce3df"/><text x="10" y="${y(v)+4}" font-size="12" fill="#607479">${pct(v)}</text>`);}positions.forEach((p,i)=>{let x=95+i*82,c=i%2?colors[1]:colors[0],lo=y(p.shootout_bootstrap_95[0]),hi=y(p.shootout_bootstrap_95[1]);parts.push(`<line x1="${x}" y1="${lo}" x2="${x}" y2="${hi}" stroke="${c}" stroke-width="2"/><circle cx="${x}" cy="${y(p.conversion)}" r="5" fill="${c}"/><text x="${x}" y="306" text-anchor="middle" font-size="12">${i%2?'B':'A'}${Math.floor(i/2)+1}</text>`);});el.innerHTML=parts.join('');}empiricalChart();table('transportTable',['Scenario','Rule','A wins','E[min(R,100)]'],F.transport.map(x=>[x.scenario,x.kind,pct(+x.win_a),num(+x.restricted_rounds)]));$('noteBody').innerHTML=F.noteHTML;update();optimize();
